head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getRowClass]<br/>Body Row 의 인덱스를 사용하여 특정 Body Row 에 설정된 CSS 클래스를 반환합니다.",
    "validation" : [
        "setRowClass() 메소드로 설정한 CSS 클래스만 반환됩니다.",
        "rowIndex(필수) 파라미터로 CSS 클래스를 조회할 Body Row 의 인덱스를 설정합니다. (0부터)",
        "useRealRowIndex(선택) 파라미터를 true 로 설정하면 rowIndex 를 DataList 의 실제 Row 인덱스로 처리합니다.",
        "useRealRowIndex(선택) 파라미터를 false(기본값) 로 설정하면 rowIndex 를 필터/정렬이 적용되어 GridView 에 표시된 Row 기준으로 처리합니다.",
        "useRealRowIndex(선택) 파라미터를 생략하면 기본값 false 로 동작합니다.",
        "설정된 CSS 클래스가 없는 경우 undefined 를 반환합니다.",
        "setRowClass() 실행 시 CSS 클래스는 Body Row 의 tr 요소에 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - dept 그룹이 섞인 데이터 6건으로 바인딩 GridView 동적 생성
//  - 필터(dept='Sales') 적용 시 표시 Row 와 DataList 실제 Row 인덱스가 달라지도록 데이터 배치
//    -> getRowClass 의 useRealRowIndex true/false 차이를 관찰하기 위함
scwin.comp_init = async function () {
    // 기존 target/dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    scwin.gFilterOn = false;

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="데이터 6건(dept 그룹 혼합). 필터(dept=Sales) 적용 시 표시 Row 와 DataList 실제 Row 인덱스가 달라지며, 이때 getRowClass 의 useRealRowIndex 값에 따라 반환되는 Row 가 달라집니다. (먼저 setRowClass 로 클래스 설정 후 getRowClass 조회)"', '', 'label1');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 6건 : dept 그룹을 섞어 배치 -> 필터 시 표시/실제 인덱스 차이 발생
    //   실제 인덱스 0:Sales 1:Dev 2:Sales 3:QA 4:Dev 5:Sales
    //   dept='Sales' 필터 시 표시 순서 -> 실제 0,2,5 (표시 인덱스 0,1,2)
    let jsonData = [
        { "name": "John", "dept": "Sales", "amount": 100 },
        { "name": "Mike", "dept": "Dev",   "amount": 200 },
        { "name": "Jane", "dept": "Sales", "amount": 300 },
        { "name": "Tom",  "dept": "QA",    "amount": 400 },
        { "name": "Amy",  "dept": "Dev",   "amount": 500 },
        { "name": "Jack", "dept": "Sales", "amount": 600 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    // Header(이름/부서/금액) + gBody(데이터). 마지막 컬럼 width="*" 로 가로 스크롤 방지
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="바인딩 그리드 (데이터 6건, dept 그룹 혼합)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// setRowClass 실행 — 조회 대상 Row 에 CSS 클래스를 미리 설정 (getRowClass 가 반환할 값 준비)
//  - rowIndex/useRealRowIndex 는 par_ 선택값을 그대로 사용
scwin.btn_setRowClass_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let className = par_className.getValue();

    // useRealRowIndex : gdl_boolean getText (미설정/true/false). 미설정이면 인자 생략
    let useRealText = par_useRealRowIndex.getText();

    if (useRealText === "") {
        target1.setRowClass(rowIndex, className);
        wf_body_bottom.getObj("scwin").setReturnValue("setRowClass(" + rowIndex + ", " + className + ") — useRealRowIndex 생략(기본 false)");
    } else {
        let useRealRowIndex = (useRealText === "true");
        target1.setRowClass(rowIndex, className, useRealRowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("setRowClass(" + rowIndex + ", " + className + ", " + useRealRowIndex + ")");
    }
}



// getRowClass 실행 — rowIndex/useRealRowIndex 로 설정된 CSS 클래스 조회 + 출력
//  - useRealRowIndex true  : rowIndex 를 DataList 실제 Row 인덱스로 처리
//  - useRealRowIndex false : rowIndex 를 화면 표시 Row 기준으로 처리
//  - useRealRowIndex 미설정 : 인자 생략 (기본 false 동작)
scwin.btn_getRowClass_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());

    // useRealRowIndex : gdl_boolean getText (미설정/true/false)
    let useRealText = par_useRealRowIndex.getText();

    let rtn;
    let trIndex;
    if (useRealText === "") {
        // 미설정 -> 인자 생략 (기본값 false 동작 확인)
        rtn = target1.getRowClass(rowIndex);
        trIndex = rowIndex;
        wf_body_bottom.getObj("scwin").setReturnValue("getRowClass(" + rowIndex + ") — useRealRowIndex 생략(기본 false) : " + rtn);
    } else {
        let useRealRowIndex = (useRealText === "true");
        rtn = target1.getRowClass(rowIndex, useRealRowIndex);
        // 표시 trIndex 계산 : false 면 rowIndex 그대로, true 면 실제 인덱스 -> getDisplayRowIndex 로 표시 인덱스 변환
        trIndex = useRealRowIndex ? target1.getDisplayRowIndex(rowIndex) : rowIndex;
        wf_body_bottom.getObj("scwin").setReturnValue("getRowClass(" + rowIndex + ", " + useRealRowIndex + ") : " + rtn);
    }

    // @spec : CSS 클래스는 Body Row 의 tr 요소에 적용됨 — 해당 Row 의 tr className 실측
    let td = (typeof trIndex === "number" && trIndex >= 0) ? document.querySelector("td[id*='target1_cell_" + trIndex + "_0']") : null;
    if (td && td.parentNode) {
        let tr = td.parentNode;
        wf_body_bottom.getObj("scwin").setReturnValue("대상 Row tr.tagName : " + tr.tagName + " / tr.className : " + tr.className);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("대상 Row tr : 표시되지 않아 접근 불가 (필터로 가려진 실제 인덱스일 수 있음)");
    }
}



// 필터 적용/해제 — dept 컬럼을 'Sales' 로 필터링.
//  - 필터 적용 시 표시 Row(3건:John/Jane/Jack)와 DataList 실제 Row 인덱스(0,2,5)가 달라짐
//  - 이 상태에서 getRowClass(1, false) 는 표시 2번째(Jane=실제 2), (1, true) 는 실제 인덱스 1(Mike) 대상
scwin.btn_toggleFilter_onclick = function () {
    if (scwin.gFilterOn === true) {
        dlt_bind.removeColumnFilterAll();
        scwin.gFilterOn = false;
        wf_body_bottom.getObj("scwin").setReturnValue("[필터 해제] 데이터 6건 전체 표시");
    } else {
        // 4번째 인자 exactMatch=true 필요 — 2-인자만으로는 필터가 적용되지 않음
        dlt_bind.setColumnFilter("dept", "Sales", "and", true);
        scwin.gFilterOn = true;
        wf_body_bottom.getObj("scwin").setReturnValue("[dept='Sales' 필터 적용] 표시 Row 3건(실제 인덱스 0,2,5). useRealRowIndex 차이를 관찰하세요.");
    }
}
